insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 3, 6, 'Base na cuento ya le, donde lugar na escuela tu anda para compra comida si tu ta senti con hambre?', 'Na cantina' from public.crla_stories where region_id = 13 and language = 'Chavacano' and grade = 3 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 4, 9, 'Donde tu anda si etu enfermo?', 'Na clinica' from public.crla_stories where region_id = 13 and language = 'Chavacano' and grade = 3 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
