insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 6, 14, 'Porque bonito anda na de ila escuela?', 'Any or all the following: mucho cosa kame ay aprende; Mucho cosas que puede encontra na de amon escuela; ta rodea este de mucho pono y flores; de amon maga maestra y maestro ta ensea con amor' from public.crla_stories where region_id = 13 and language = 'Chavacano' and grade = 3 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 7, 15, 'Que modo ta ensea maga maestra y maestro na escuela?', 'Ta ensea con amor' from public.crla_stories where region_id = 13 and language = 'Chavacano' and grade = 3 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
