insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 2, 3, 'Cosa sila ya mira un dia?', 'grupada de pajaro ta vola' from public.crla_stories where region_id = 13 and language = 'Chavacano' and grade = 3 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 3, 5, 'Base na cuento donde ay anda el maga pajaro?', 'Para na oeste o na oeste' from public.crla_stories where region_id = 13 and language = 'Chavacano' and grade = 3 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 4, 7, 'Quien quiere segui con el maga pajaro?', 'Quiere le mira bonito lugar' from public.crla_stories where region_id = 13 and language = 'Chavacano' and grade = 3 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
