insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 1, 1, 'Sin-o ang nagapanglapta sang basura?', 'Si Marko' from public.crla_stories where region_id = 13 and language = 'Hiligaynon' and grade = 2 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 2, 3, 'Ano ang mga basura nga ginapangwigit niya?', 'Putos sang tinapay kag dulse' from public.crla_stories where region_id = 13 and language = 'Hiligaynon' and grade = 2 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 3, 5, 'Base sa damgo ni Marko, ano ang iya ginhimo?', 'Nagdalagan sia sing madasig.' from public.crla_stories where region_id = 13 and language = 'Hiligaynon' and grade = 2 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 4, 6, 'Ngaa nagdalagan sia sing madasig?', 'Kay ginalagas sia sang mabaho nga grupo sang basura.' from public.crla_stories where region_id = 13 and language = 'Hiligaynon' and grade = 2 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 5, 11, 'Ngaa nagasinggit kag ginakulbaan si Marko?', 'Kay ginhigop sia; Kay ginlagas sia; Kay nagdamgo sia' from public.crla_stories where region_id = 13 and language = 'Hiligaynon' and grade = 2 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 6, 12, 'Ngaa naghambal si Marko nga indi na sia manglapta sang basura?', 'Kay nahadlok sia sa basura; Kay nahadlok sia nga higupon/ magdamgo parte sa basura.' from public.crla_stories where region_id = 13 and language = 'Hiligaynon' and grade = 2 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 1, 1, 'Sin-o ang malipayon nga bata?', 'Si Ramon' from public.crla_stories where region_id = 13 and language = 'Hiligaynon' and grade = 2 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 2, 2, 'Sin-o ang ginahulat ni Ramon kada adlaw?', 'Si Nanay/Mama/Iloy/Mommy' from public.crla_stories where region_id = 13 and language = 'Hiligaynon' and grade = 2 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 3, 3, 'Ano ang nabatyagan ni Ramon kada mag-abot ang iya Nanay?', 'Nasadyahan/nalipay/excited' from public.crla_stories where region_id = 13 and language = 'Hiligaynon' and grade = 2 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 4, 7, 'Ano ang unod sang itlog nga dala ni Nanay?', 'Hampanganan/toys/halampangan/kinder joy' from public.crla_stories where region_id = 13 and language = 'Hiligaynon' and grade = 2 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 5, 12, 'Ngaa para kay Ramon, isa ka sorpresa si Nanay?', 'Kay si Nanay ang ginahulat ni Ramon magpauli sa balay. Kay nalipay sia nga nagaabot/nagapuli si Nanay sa balay. Kay palangga ni Ramon si Nanay. Tungod nagadala si Nanay sang hampanganan/pasalubong/sorpresa para kay Ramon. Tungod kay palangga ni Ramon si Nanay.' from public.crla_stories where region_id = 13 and language = 'Hiligaynon' and grade = 2 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 6, 13, 'Ngaa tuman ang kalipay ni Nanay sa ginhimo ni Ramon?', 'Kay wala nasubuan si Ramon bisan wala sia dala nga hampanganan/sorpresa. Kay naintindihan ni Ramon kon ngaa wala si Nanay dala nga sorpresa. Kay wala naghibi si Ramon nga wala dala si Nanay sang hampanganan/toys/kinder joy/sorpresa. Kay ginhakus ni Ramon si Nanay. Kay nakita ni Nanay nga maayo ang sitwasyon/kahimtangan ni Ramon. Kay nakita ni Nanay nga nalipay gihapon si Ramon biskan wala sia dala nga hampanganan/sorpresa.' from public.crla_stories where region_id = 13 and language = 'Hiligaynon' and grade = 2 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
