insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 3, 4, 'Mamin-ano a tumuktok ti Manok sa bugawen ni Kibol?', 'Maminlima a tumuktok. Maminlima a mapan ni Manok.' from public.crla_stories where region_id = 13 and language = 'Ilokano' and grade = 3 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 4, 7, 'Ania ti aramiden ni Kibol no agdamag kenkuana ni Tata Kandro?', 'Kaipapananna ti gungundawayan ni Manok ti kinasayaat ni Kibol.' from public.crla_stories where region_id = 13 and language = 'Ilokano' and grade = 3 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 5, 12, 'Asino ti napan nagtuktok iti pagay?', 'Manok' from public.crla_stories where region_id = 13 and language = 'Ilokano' and grade = 3 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 6, 14, 'Apay a binugaw ni Kibol ti Manok iti naminlima?', 'Gapu ta naminlima nga immay ni Manok.' from public.crla_stories where region_id = 13 and language = 'Ilokano' and grade = 3 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 7, 17, 'Apay a magusgustuan ni Tata Kandro ni Kibol?', 'Gapu ta saan a naimut ni Kibol.' from public.crla_stories where region_id = 13 and language = 'Ilokano' and grade = 3 and story_no = 1 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 1, 1, 'Asino ti naganak iti isla?', 'Ni Ugsa ti naganak.' from public.crla_stories where region_id = 13 and language = 'Ilokano' and grade = 3 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 2, 4, 'Ania ti langa ti urbon ni ugsa?', 'Nalungpo ti urbon ni Ugsa.' from public.crla_stories where region_id = 13 and language = 'Ilokano' and grade = 3 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 3, 5, 'Ania ti nagtutulagan dagiti ayup idi maamuanda a naganak ni Ugsa?', 'Mapanda kitaen da Ugsa; Nagtutulaganda a mapan kano kitaen da Ugsa.' from public.crla_stories where region_id = 13 and language = 'Ilokano' and grade = 3 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 4, 12, 'Kasano ti panagdaliasat dagiti ayup a mapan ken ni Ugsa ken ti urbonna?', 'Nagtayab, naglagtolagto, naglangoy, ken naguyasda.' from public.crla_stories where region_id = 13 and language = 'Ilokano' and grade = 3 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 5, 12, 'Sadino ti nakasarakanda ken ni Ugsa ken ti urbonna?', 'Iti igid ti karayan.' from public.crla_stories where region_id = 13 and language = 'Ilokano' and grade = 3 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 6, 15, 'Apay a nagyaman ni Ugsa kadagiti ayup?', 'Gapu ti isasarungkarda, gapu ti ibibisitada' from public.crla_stories where region_id = 13 and language = 'Ilokano' and grade = 3 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
insert into public.crla_story_questions (story_id, question_no, after_sentence, question, accepted_answers) select id, 7, 16, 'Apay a nagsasala ken nagkakanta dagiti ayup?', 'Gapu ta naragsakda. Gapu ta naganak ni Ugsa. Gapu ta nakitadan ti urbon ni Ugsa.' from public.crla_stories where region_id = 13 and language = 'Ilokano' and grade = 3 and story_no = 2 on conflict (story_id, question_no) do update set after_sentence = excluded.after_sentence, question = excluded.question, accepted_answers = excluded.accepted_answers;
